(6316920, 930904, 116649, '<td valign="top">Monterey?  Beautiful image!</td>', 'Monterey?  Beautiful image!', '2011-02-16 12:36:43.000000', NULL, 1),
(6316964, 933851, 118154, '<td valign="top">Great stuff.</td>', 'Great stuff.', '2011-02-16 12:53:30.000000', NULL, 1),
