(6320626, 930301, 60047, '<td valign="top">Interesting high contrast composition.Wonderfully dark.</td>', 'Interesting high contrast composition.Wonderfully dark.', '2011-02-19 09:29:01.000000', NULL, 1),
(6320628, 930227, 49652, '<td valign="top">Cute!</td>', 'Cute!', '2011-02-19 09:29:11.000000', NULL, 1),
(6320629, 934708, 127608, '<td valign="top">Wow love it...</td>', 'Wow love it...', '2011-02-19 09:29:24.000000', NULL, 1),
(6320630, 935470, 49652, '<td valign="top">Stunning!  The colors are gorgeous!</td>', 'Stunning!  The colors are gorgeous!', '2011-02-19 09:29:50.000000', NULL, 1),
(6320631, 934215, 60047, '<td valign="top">Technically a good shot of the porch light. But I don''t follow the purpose of the shot - and the title does not help me.</td>', 'Technically a good shot of the porch light. But I don''t follow the purpose of the shot - and the title does not help me.', '2011-02-19 09:31:12.000000', NULL, 1),
(6320632, 934652, 60047, '<td valign="top">I love the colors in this shot. I don''t quite follow the compositional choice. Love the textures rendered in post processing.</td>', 'I love the colors in this shot. I don''t quite follow the compositional choice. Love the textures rendered in post processing.', '2011-02-19 09:32:30.000000', NULL, 1),
(6320633, 932818, 60047, '<td valign="top">A classic shot here on DPC. The post processing is strong enough so that you appear to be trying to achieve an effect rather than making the mistake of over-doing the saturation. Interesting colors result. Great focus management.</td>', 'A classic shot here on DPC. The post processing is strong enough so that you appear to be trying to achieve an effect rather than making the mistake of over-doing the saturation. Interesting colors result. Great focus management.', '2011-02-19 09:34:19.000000', NULL, 1),
(6320640, 932234, 92577, '<td valign="top">the clever thing about it being indistinct is that you want to see more<br/> - good luck</td>', 'the clever thing about it being indistinct is that you want to see more - good luck', '2011-02-19 09:52:35.000000', NULL, 1),
(6320642, 933539, 92577, '<td valign="top">lovely</td>', 'lovely', '2011-02-19 09:56:17.000000', NULL, 1),
(6320649, 935650, 60047, '<td valign="top">Nice abstract.Very bright.</td>', 'Nice abstract.Very bright.', '2011-02-19 10:04:27.000000', NULL, 1),
(6320650, 932007, 60047, '<td valign="top">Beautiful rendition of a frequently photographed subject. Nice work on managing the light.</td>', 'Beautiful rendition of a frequently photographed subject. Nice work on managing the light.', '2011-02-19 10:06:06.000000', NULL, 1),
(6320652, 935367, 60047, '<td valign="top">I like the contrast between the lush green and the sand hill in the BG. I think the shot would be improved if the focus was on the sail boat instead of the building.</td>', 'I like the contrast between the lush green and the sand hill in the BG. I think the shot would be improved if the focus was on the sail boat instead of the building.', '2011-02-19 10:09:04.000000', NULL, 1),
(6320656, 935701, 60047, '<td valign="top">Interesting choice of darkness. Regarding the centered composition - I am wondering why the large amount of negative space?</td>', 'Interesting choice of darkness. Regarding the centered composition - I am wondering why the large amount of negative space?', '2011-02-19 10:16:00.000000', NULL, 1),
(6320659, 932331, 60047, '<td valign="top">This is fun - evocative of classic summer fun. A noticeably dark exposure choice.</td>', 'This is fun - evocative of classic summer fun. A noticeably dark exposure choice.', '2011-02-19 10:20:53.000000', NULL, 1),
(6320660, 931092, 60047, '<td valign="top">Interesting in how the buildings are so sharp and crisp and the clouds/fog is so splotchy.</td>', 'Interesting in how the buildings are so sharp and crisp and the clouds/fog is so splotchy.', '2011-02-19 10:23:18.000000', NULL, 1),
(6320661, 935495, 60047, '<td valign="top">Great light management considering the harsh conditions.Great expressions captured. Nice colors.</td>', 'Great light management considering the harsh conditions.Great expressions captured. Nice colors.', '2011-02-19 10:26:08.000000', NULL, 1),
(6320662, 930536, 60047, '<td valign="top">Nice capture. Really speaks to the title.</td>', 'Nice capture. Really speaks to the title.', '2011-02-19 10:27:02.000000', NULL, 1),
