INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6320874, 935379, 60047, '<td valign="top">A apt ode to winter!</td>', 'A apt ode to winter!', '2011-02-19 13:50:06.000000', NULL, 1),
