INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6322005, 935670, 60047, '<td valign="top">Good focus management - right on the eye.</td>', 'Good focus management - right on the eye.', '2011-02-20 11:30:12.000000', NULL, 1),
(6322006, 935708, 60047, '<td valign="top">The blue is almost too much, here.Quite a stunning shot.</td>', 'The blue is almost too much, here.Quite a stunning shot.', '2011-02-20 11:30:53.000000', NULL, 1),
(6322008, 933612, 60047, '<td valign="top">What a great shot. The rail lines are quite unexpected and really make this photo pop. Very nice work.</td>', 'What a great shot. The rail lines are quite unexpected and really make this photo pop. Very nice work.', '2011-02-20 11:32:06.000000', NULL, 1),
(6322009, 935676, 60047, '<td valign="top">Beautiful. Surreal, even.</td>', 'Beautiful. Surreal, even.', '2011-02-20 11:33:45.000000', NULL, 1),
(6322010, 932963, 60047, '<td valign="top">A wonderfully dramatic sky.</td>', 'A wonderfully dramatic sky.', '2011-02-20 11:34:38.000000', NULL, 1),
(6322013, 933779, 60047, '<td valign="top">What a neat shot - not only the various ridge lines, but to have captured the clouds as they appear to be spilling out from the right and over the closest ridge. Cool!</td>', 'What a neat shot - not only the various ridge lines, but to have captured the clouds as they appear to be spilling out from the right and over the closest ridge. Cool!', '2011-02-20 11:35:51.000000', NULL, 1),
(6322014, 935237, 60047, '<td valign="top">Beautiful. Great colors. I would change two things about her pose to make her look more comfortable and at ease - lift her head up a bit and then un-clench her fist on her right hand.</td>', 'Beautiful. Great colors. I would change two things about her pose to make her look more comfortable and at ease - lift her head up a bit and then un-clench her fist on her right hand.', '2011-02-20 11:37:48.000000', NULL, 1),
(6322015, 933059, 60047, '<td valign="top">Very pretty night shot.</td>', 'Very pretty night shot.', '2011-02-20 11:38:07.000000', NULL, 1),
(6322017, 934708, 60047, '<td valign="top">What an interesting feaux window! I love her pose - but I think the use of the drapes is almost a bit too modest. This type of shot begs for at least a bit of decolletage!</td>', 'What an interesting feaux window! I love her pose - but I think the use of the drapes is almost a bit too modest. This type of shot begs for at least a bit of decolletage!', '2011-02-20 11:42:17.000000', NULL, 1),
(6322018, 935570, 60047, '<td valign="top">Nice tension between dark and light captured here.</td>', 'Nice tension between dark and light captured here.', '2011-02-20 11:42:55.000000', NULL, 1),
(6322019, 934514, 86218, '<td valign="top">Rise above the Masses. Really a shot with impact. Makes you think. Great shot</td>', 'Rise above the Masses. Really a shot with impact. Makes you think. Great shot', '2011-02-20 11:45:50.000000', NULL, 1),
(6322020, 935527, 60047, '<td valign="top">Great soft pastels in this shot. I am assuming this is a negative?</td>', 'Great soft pastels in this shot. I am assuming this is a negative?', '2011-02-20 11:48:39.000000', NULL, 1),
(6322021, 935456, 60047, '<td valign="top">A peaceful, idyllic shot.</td>', 'A peaceful, idyllic shot.', '2011-02-20 11:49:09.000000', NULL, 1),
(6322023, 935137, 86218, '<td valign="top">Beautiful! Nice timeing. Patient photographer</td>', 'Beautiful! Nice timeing. Patient photographer', '2011-02-20 11:50:25.000000', NULL, 1),
(6322024, 934219, 60047, '<td valign="top">What a nice photo of a mother and her children.</td>', 'What a nice photo of a mother and her children.', '2011-02-20 11:50:30.000000', NULL, 1),
(6322025, 934674, 60047, '<td valign="top">The focus appears to be on the dog''s face and not quite on the boys'' faces. A great shot of the four!</td>', 'The focus appears to be on the dog''s face and not quite on the boys'' faces. A great shot of the four!', '2011-02-20 11:51:28.000000', NULL, 1),
