(6322040, 935354, 60047, '<td valign="top">A beautiful portrait of mother and son. This could be made even better by using a mask and then selectively softening the chin, cheeks and forehead of mom''s face.</td>', 'A beautiful portrait of mother and son. This could be made even better by using a mask and then selectively softening the chin, cheeks and forehead of mom''s face.', '2011-02-20 11:58:42.000000', NULL, 1),
(6322043, 933909, 60047, '<td valign="top">Looks pretty darned foreboding!</td>', 'Looks pretty darned foreboding!', '2011-02-20 11:59:17.000000', NULL, 1),
