(6322050, 935338, 86218, '<td valign="top">Nice portrait. Natural looking and thanks so much for not pushing the processing on this!!!</td>', 'Nice portrait. Natural looking and thanks so much for not pushing the processing on this!!!', '2011-02-20 12:02:23.000000', NULL, 1),
(6322053, 933612, 86218, '<td valign="top">Simplicity - Great shot. Love it</td>', 'Simplicity - Great shot. Love it', '2011-02-20 12:06:21.000000', NULL, 1),
