(6322264, 935531, 60047, '<td valign="top">Great perspective and Title.</td>', 'Great perspective and Title.', '2011-02-20 13:57:14.000000', NULL, 1),
(6322265, 933189, 65234, '<td valign="top">Lucky you to see and shoot this scene!</td>', 'Lucky you to see and shoot this scene!', '2011-02-20 13:57:31.000000', NULL, 1),
